questionvariables.text:
/*general and fertility rates*/
age:rand(3)+4;
age_group1:rand_with_step(14,16,5);
age_group2:age_group1+age;
age_group3:age_group2+age;
age_group4:age_group3+age;
age_group5:age_group4+age;
age_group6:age_group5+age;
age_group7:age_group6+age;
age_group8:age_group7+age;

/*Female population (‘000’)*/
fem_pop1:rand_with_step(1000,2000,5);
fem_pop2:rand_with_prohib(1000,2000,[fem_pop1]);
fem_pop3:rand_with_prohib(1000,2000,[fem_pop1,fem_pop2]);
fem_pop4:rand_with_prohib(1000,2000,[fem_pop1,fem_pop2,fem_pop3]);
fem_pop5:rand_with_prohib(1000,2000,[fem_pop1,fem_pop2,fem_pop3,fem_pop4]);
fem_pop6:rand_with_prohib(1000,2000,[fem_pop1,fem_pop2,fem_pop3,fem_pop4,fem_pop5]);
fem_pop7:rand_with_prohib(1000,2000,[fem_pop1,fem_pop2,fem_pop3,fem_pop4,fem_pop5,fem_pop6]);
 /*Total fem pop*/
fem_popt1:fem_pop1*1000;
fem_popt2:fem_pop2*1000;
fem_popt3:fem_pop3*1000;
fem_popt4:fem_pop4*1000;
fem_popt5:fem_pop5*1000;
fem_popt6:fem_pop6*1000;
fem_popt7:fem_pop7*1000;

/*Female births*/
fem_birth1:rand_with_step(5000,100000,1);
fem_birth2:rand_with_prohib(5000,100000,[fem_birth1]);
fem_birth3:rand_with_prohib(5000,100000,[fem_birth1,fem_birth2]);
fem_birth4:rand_with_prohib(5000,100000,[fem_birth1,fem_birth2,fem_birth3]);
fem_birth5:rand_with_prohib(5000,100000,[fem_birth1,fem_birth2,fem_birth3,fem_birth4]);
fem_birth6:rand_with_prohib(5000,100000,[fem_birth1,fem_birth2,fem_birth3,fem_birth4,fem_birth5]);
fem_birth7:rand_with_prohib(5000,100000,[fem_birth1,fem_birth2,fem_birth3,fem_birth4,fem_birth5,fem_birth6]);


/*Survival rate*/
surv_r1:rand_with_step(10,25,1);
surv_r2:rand_with_step(10,25,1);
surv_r3:rand_with_step(10,25,1);
surv_r4:rand_with_step(10,25,1);
surv_r5:rand_with_step(10,25,1);
surv_r6:rand_with_step(10,25,1);
surv_r7:rand_with_step(10,25,1);

srv1:rand_with_step(800,820,1);
srv2:srv1+surv_r1;
srv3:srv2+surv_r2;
srv4:srv3+surv_r3;
srv5:srv4+surv_r4;
srv6:srv5+surv_r5;
srv7:srv6+surv_r6;

surv_rate1:float(srv7/1000);
surv_rate2:float(srv6/1000);
surv_rate3:float(srv5/1000);
surv_rate4:float(srv4/1000);
surv_rate5:float(srv3/1000);
surv_rate6:float(srv2/1000);
surv_rate7:float(srv1/1000);

/*worked solution variables*/
ASFR_1:decimalplaces((fem_birth1/fem_popt1),4);
ASFR_2:decimalplaces((fem_birth2/fem_popt2),4);
ASFR_3:decimalplaces((fem_birth3/fem_popt3),4);
ASFR_4:decimalplaces((fem_birth4/fem_popt4),4);
ASFR_5:decimalplaces((fem_birth5/fem_popt5),4);
ASFR_6:decimalplaces((fem_birth6/fem_popt6),4);
ASFR_7:decimalplaces((fem_birth7/fem_popt7),4);
sum_ASFR:decimalplaces((ASFR_1+ASFR_2+ASFR_3+ASFR_4+ASFR_5+ASFR_6+ASFR_7),4);

/*ASFR*Survival rate(S)*/
ASFR_s1:decimalplaces((ASFR_1*surv_rate1),4);
ASFR_s2:decimalplaces((ASFR_2*surv_rate2),4);
ASFR_s3:decimalplaces((ASFR_3*surv_rate3),4);
ASFR_s4:decimalplaces((ASFR_4*surv_rate4),4);
ASFR_s5:decimalplaces((ASFR_5*surv_rate5),4);
ASFR_s6:decimalplaces((ASFR_6*surv_rate6),4);
ASFR_s7:decimalplaces((ASFR_7*surv_rate7),4);
sum_ASFR_s:ASFR_s1+ASFR_s2+ASFR_s3+ASFR_s4+ASFR_s5+ASFR_s6+ASFR_s7;
/*model answers*/
ta1:decimalplaces((sum_ASFR*age),4);/*Gross Reproduction Rate (GRR)*/
ta2:decimalplaces(sum_ASFR_s*age,4);
